	public Paragraph generateSearchCriteria(Map<String, String> inputParams) {
		Paragraph searchCriteria = new Paragraph();

		String searchDescription = inputParams.get(DBPUtilitiesConstants.SEARCH_DESCRIPTION);
		String searchMinAmount = inputParams.get(DBPUtilitiesConstants.SEARCH_MIN_AMOUNT);
		String searchMaxAmount = inputParams.get(DBPUtilitiesConstants.SEARCH_MAX_AMOUNT);
		String searchStartDate = inputParams.get(DBPUtilitiesConstants.SEARCH_START_DATE);
		String searchEndDate = inputParams.get(DBPUtilitiesConstants.SEARCH_END_DATE);
		String transactionType = inputParams.get(DBPUtilitiesConstants.TRANSACTION_TYPE);
		String checkRangeStart = inputParams.get(DBPUtilitiesConstants.FRM_CHK_NUMBER);
		String checkRangeEnd = inputParams.get(DBPUtilitiesConstants.TO_CHK_NUMBER);
		String dateRange = inputParams.get(DBPUtilitiesConstants.SEARCH_DATE);
		
		String searchTransactionType = inputParams.get(DBPUtilitiesConstants.SEARCH_TRANS_TYPE);
		
		String lockReason = inputParams.get("lockReason");
		String lockedEventId = inputParams.get("lockedEventId");

		
		searchCriteria.add(new Chunk("Date Range: ", sourceSansProBold));
//		String dateRangeText = "";
//		if (dateRange != null && "CustomDateRange".equalsIgnoreCase(dateRange)) {
//			dateRangeText = "From " + searchStartDate + " to " + searchEndDate; // TODO: Formatting
//		} else {
//			if (searchStartDate != null && searchEndDate != null)
//				dateRangeText = searchStartDate + " - " + searchEndDate;
//			else
//				dateRangeText = " Last " + dateRange;
//		}
		String dateRangeText = "";
		if (dateRange != null && "CustomDateRange".equalsIgnoreCase(dateRange)) {
			dateRangeText = "From " + formatPdfDateRange(searchStartDate, searchEndDate, " to ");
		} else {
			if (searchStartDate != null && searchEndDate != null)
				dateRangeText = formatPdfDateRange(searchStartDate, searchEndDate, " - ");
			else
				dateRangeText = " Last " + dateRange;
		}
		searchCriteria.add(new Chunk(dateRangeText, valueFont));
		
		if("Blocked".equalsIgnoreCase(searchTransactionType)) {
			
			if (lockReason != null && !"".equals(lockReason)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Keyword: ", sourceSansProBold));
				searchCriteria.add(new Chunk(lockReason, valueFont));
			}
			if (lockedEventId != null && !"".equals(lockedEventId)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Reference Number: ", sourceSansProBold));
				searchCriteria.add(new Chunk(lockedEventId, valueFont));
			}
			
		}else {
			if (searchDescription != null && !"".equals(searchDescription)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Keyword: ", sourceSansProBold));
				searchCriteria.add(new Chunk(searchDescription, valueFont));
			}

			if (searchMinAmount != null && !"".equals(searchMinAmount)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Amount Range: ", sourceSansProBold));
				String amtRange = searchMinAmount + " to " + searchMaxAmount; // TODO: Formatting
				searchCriteria.add(new Chunk(amtRange, valueFont));
			}
			if (transactionType != null && !"".equals(transactionType)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Transaction Type: ", sourceSansProBold));
				searchCriteria.add(new Chunk(transactionType, valueFont));
			}
			if (checkRangeStart != null && !"".equals(checkRangeStart)) {
				searchCriteria.add(new Chunk(", ", valueFont));
				searchCriteria.add(new Chunk("Check Number: ", sourceSansProBold));
				String checkRange = checkRangeStart + " to " + checkRangeEnd; // TODO: Formatting
				searchCriteria.add(new Chunk(checkRange, valueFont));
			}
		}
		
		

		return searchCriteria;

	}

	//HBL CHANGES
	/**
	 * PDF display only. Renders the statement search date range with the month spelled out in
	 * full English, so a customer can never read a date the wrong way round.
	 *
	 * The raw request values reaching this class are not reliably yyyy-MM-dd: the channel sends
	 * unpadded months (2026-2-06) and, for some downloads, day and month transposed (2026-08-02
	 * meaning 08-Feb-2026). Component order is resolved the same way the API-side preprocessor
	 * resolves it - self-evident endpoint, then sibling inheritance, then range coherence. No
	 * business value is altered; only the printed string changes.
	 *
	 * @param rawStartDate raw searchStartDate from inputParams
	 * @param rawEndDate   raw searchEndDate from inputParams
	 * @param separator    text between the two dates, e.g. " - " or " to "
	 * @return e.g. "2026-February-08 - 2026-May-06"; the untouched inputs on any parse failure
	 */
	private String formatPdfDateRange(String rawStartDate, String rawEndDate, String separator) {
		int[] start = splitPdfDateParts(rawStartDate);
		int[] end = splitPdfDateParts(rawEndDate);

		if (start == null || end == null) {
			return StringUtils.defaultString(rawStartDate) + separator + StringUtils.defaultString(rawEndDate);
		}

		boolean dayFirst = resolvePdfDayFirst(start, end);
		return renderPdfDate(start, dayFirst) + separator + renderPdfDate(end, dayFirst);
	}

	/** Splits a raw date into { year, first, second }; null when it is not a recognisable date. */
	private int[] splitPdfDateParts(String rawDate) {
		if (StringUtils.isBlank(rawDate)) {
			return null;
		}
		String value = rawDate.trim();
		try {
			if (value.matches("\\d{8}")) { // yyyyMMdd
				return new int[] { Integer.parseInt(value.substring(0, 4)), Integer.parseInt(value.substring(4, 6)),
						Integer.parseInt(value.substring(6, 8)) };
			}
			String[] parts = value.split("[-/.]");
			if (parts.length != 3) {
				return null;
			}
			int a = Integer.parseInt(parts[0].trim());
			int b = Integer.parseInt(parts[1].trim());
			int c = Integer.parseInt(parts[2].trim());
			if (a > 31) { // year first - yyyy ? ?
				return new int[] { a, b, c };
			}
			if (c > 31) { // year last - ? ? yyyy
				return new int[] { c, a, b };
			}
			return null; // no identifiable year, leave the value alone
		} catch (NumberFormatException e) {
			return null;
		}
	}

	/** true when both endpoints must be read as yyyy-dd-MM rather than yyyy-MM-dd. */
	private boolean resolvePdfDayFirst(int[] start, int[] end) {
		Boolean startProof = provenPdfDayFirst(start);
		Boolean endProof = provenPdfDayFirst(end);

		if (startProof != null && endProof != null && startProof.equals(endProof)) {
			return startProof.booleanValue();
		}
		if (startProof != null && endProof == null) {
			return startProof.booleanValue(); // sibling inheritance
		}
		if (endProof != null && startProof == null) {
			return endProof.booleanValue(); // sibling inheritance
		}

		// Both ambiguous, or the two proofs disagree: the reading that gives a
		// non-inverted range wins.
		long monthFirstStart = pdfSortKey(start, false);
		long monthFirstEnd = pdfSortKey(end, false);
		if (monthFirstStart > 0 && monthFirstEnd > 0 && monthFirstStart <= monthFirstEnd) {
			return false;
		}
		long dayFirstStart = pdfSortKey(start, true);
		long dayFirstEnd = pdfSortKey(end, true);
		if (dayFirstStart > 0 && dayFirstEnd > 0 && dayFirstStart <= dayFirstEnd) {
			return true;
		}
		return false; // nothing proves otherwise - keep ISO order
	}

	/** FALSE = provably yyyy-MM-dd, TRUE = provably yyyy-dd-MM, null = both readings are real dates. */
	private Boolean provenPdfDayFirst(int[] parts) {
		boolean monthFirstValid = isValidPdfDate(parts[0], parts[1], parts[2]);
		boolean dayFirstValid = isValidPdfDate(parts[0], parts[2], parts[1]);
		if (monthFirstValid && !dayFirstValid) {
			return Boolean.FALSE;
		}
		if (dayFirstValid && !monthFirstValid) {
			return Boolean.TRUE;
		}
		return null;
	}

	private long pdfSortKey(int[] parts, boolean dayFirst) {
		int month = dayFirst ? parts[2] : parts[1];
		int day = dayFirst ? parts[1] : parts[2];
		if (!isValidPdfDate(parts[0], month, day)) {
			return -1L;
		}
		return parts[0] * 10000L + month * 100L + day;
	}

	private boolean isValidPdfDate(int year, int month, int day) {
		if (year < 1 || month < 1 || month > 12 || day < 1) {
			return false;
		}
		int[] lengths = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
		int maxDay = lengths[month - 1];
		if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0)) {
			maxDay = 29;
		}
		return day <= maxDay;
	}

	/** "2026-February-08" - month spelled out, day zero padded. */
	private String renderPdfDate(int[] parts, boolean dayFirst) {
		int month = dayFirst ? parts[2] : parts[1];
		int day = dayFirst ? parts[1] : parts[2];
		if (month < 1 || month > 12) {
			return parts[0] + "-" + StringUtils.leftPad(String.valueOf(parts[1]), 2, '0') + "-"
					+ StringUtils.leftPad(String.valueOf(parts[2]), 2, '0');
		}
		return parts[0] + "-" + PDF_MONTH_NAMES[month - 1] + "-"
				+ StringUtils.leftPad(String.valueOf(day), 2, '0');
	}
	
