	private void addTransactionsData(JsonArray data, PdfPTable transTable) {
		if (null != data && data.size() > 0) {
			for (int i = 0; i < data.size(); i++) {
				JsonObject rowData = data.get(i).getAsJsonObject();

				/** description replace with transactionsNotes from actual data.**/
				if(rowData.has("description")) {
					diagnostic.debug("rowData before: ##"+ rowData);
					JsonElement val = rowData.get("description");
					diagnostic.debug("description val: ##"+ val);
					rowData.remove("description");
					rowData.add("transactionsNotes", val);
					diagnostic.debug("rowData after: ##"+ rowData);
				}
				
				addRow(transTable, rowData, this.fields);
				String amount = "";
				if (rowData.has("amount") && !rowData.get("amount").isJsonNull()) {
					amount = rowData.get("amount").getAsString();
				}

				amount = com.kony.dbputilities.util.CommonUtils.formatDecimal(amount);
				PdfPCell amtCell = new PdfPCell();
				amtCell.setBorder(0);
				amtCell.setPhrase(new Phrase(amount, this.valueFont));
				amtCell.setHorizontalAlignment(Element.ALIGN_RIGHT);
				amtCell.setPaddingTop(6);
				if (!amount.startsWith("-")) {
					transTable.addCell(getCell());
					transTable.addCell(amtCell);
				} else {
					transTable.addCell(amtCell);
					transTable.addCell(getCell());
				}
				
				String frmAcctBal = "";
				if (rowData.has("fromAccountBalance")) {
					frmAcctBal = rowData.get("fromAccountBalance").getAsString();
					frmAcctBal = com.kony.dbputilities.util.CommonUtils.formatDecimal(frmAcctBal);
				}
					PdfPCell balanceCell = new PdfPCell();
					balanceCell.setBorder(0);
					balanceCell.setHorizontalAlignment(Element.ALIGN_RIGHT);
					balanceCell.setPhrase(new Phrase(frmAcctBal, this.valueFont));
					balanceCell.setPaddingTop(6);
					transTable.addCell(balanceCell);
				
			}
			addClosingBalanceRow(transTable);    // HBL closing balance footer row
		}
	}
	
	/**
	 * HBL: openingBalance / closingBalance are per BOOKING DATE, not per transaction
	 * and not per statement. Every row of the same booking date carries the same pair.
	 * (Enquiry AC.API.NOF.TRANSACTIONS.2.0.0, conversion routine HBL.CONV.TXN.BAL.)
	 *
	 * Statement Opening Balance = openingBalance of the OLDEST booking date in the array
	 * Statement Closing Balance = closingBalance of the NEWEST booking date in the array
	 */
	private void extractStatementBalances(JsonArray data) {
		this.statementOpeningBalance = "";
		this.statementClosingBalance = "";
		if (null == data || data.size() == 0) {
			return;
		}
		String minDate = null;
		String maxDate = null;
		for (int i = 0; i < data.size(); i++) {
			JsonObject rowData = data.get(i).getAsJsonObject();
			String bookingDate = "";
			if (rowData.has("postedDate") && !rowData.get("postedDate").isJsonNull()) {
				bookingDate = rowData.get("postedDate").getAsString();
			} else if (rowData.has("transactionDate") && !rowData.get("transactionDate").isJsonNull()) {
				bookingDate = rowData.get("transactionDate").getAsString();
			}
			if (StringUtils.isBlank(bookingDate)) {
				continue;
			}
			if (minDate == null || bookingDate.compareTo(minDate) < 0) {
				minDate = bookingDate;
				if (rowData.has("openingBalance") && !rowData.get("openingBalance").isJsonNull()) {
					this.statementOpeningBalance = rowData.get("openingBalance").getAsString();
				}
			}
			if (maxDate == null || bookingDate.compareTo(maxDate) > 0) {
				maxDate = bookingDate;
				if (rowData.has("closingBalance") && !rowData.get("closingBalance").isJsonNull()) {
					this.statementClosingBalance = rowData.get("closingBalance").getAsString();
				}
			}
		}
		diagnostic.prepareDebug("HBL## statement openingBalance=" + this.statementOpeningBalance
				+ ", closingBalance=" + this.statementClosingBalance).log();
	}
	
	/**
	 * HBL: renders the statement closing balance as the last row of the Balance column.
	 * Columns 1-5 are left empty; the Balance column shows "Closing Balance" over the value.
	 */
	private void addClosingBalanceRow(PdfPTable transTable) {
		if (StringUtils.isBlank(this.statementClosingBalance)) {
			return;
		}
		PdfPCell spacerCell = new PdfPCell();
		spacerCell.setBorder(Rectangle.NO_BORDER);
		spacerCell.setColspan(5);
		transTable.addCell(spacerCell);

		Paragraph closingPara = new Paragraph();
		closingPara.add(new Chunk("Closing Balance", sourceSansProBold));
		closingPara.add(Chunk.NEWLINE);
		closingPara.add(new Chunk(com.kony.dbputilities.util.CommonUtils
				.formatDecimal(this.statementClosingBalance), sourceSansProBold));
		closingPara.setAlignment(Element.ALIGN_RIGHT);

		PdfPCell closingCell = new PdfPCell();
		closingCell.setBorder(Rectangle.TOP);
		closingCell.setBorderColor(Color.LIGHT_GRAY);
		closingCell.setPaddingTop(8f);
		closingCell.setPaddingRight(4f);
		closingCell.addElement(closingPara);
		transTable.addCell(closingCell);
	}

	public PdfPCell getCell() {
		PdfPCell pdfPCell = new PdfPCell();
		pdfPCell.setBorder(0);
		return pdfPCell;
	}

	public PdfPCell getCell(Phrase phrase) {
		PdfPCell pdfPCell = getCell();
		pdfPCell.addElement(phrase);
		return pdfPCell;
	}

	private void addRow(PdfPTable transTable, JsonObject rowData, String[] fields) {
		try {
			for (int i = 0; i < fields.length; i++) {
				PdfPCell cell = new PdfPCell();
				boolean isAmountField = false;
				if (rowData.has(fields[i])) {
					String data = rowData.get(fields[i]).getAsString();
					if ("transactionDate".equals(fields[i]) || "Date".equals(fields[i]) || "fromDate".equals(fields[i])
							|| "toDate".equals(fields[i]) || "creditValueDate".equals(fields[i])) {
						data = HelperMethods.convertDateFormat(data, this.dateFormat);
					} else if ("amount".equals(fields[i]) || "fromAccountBalance".equals(fields[i])
							|| "lockedAmount".equals(fields[i]) || "OutstandingBalance".equals(fields[i])
							|| "Charges".equals(fields[i]) || "Principal".equals(fields[i])
							|| "Interest".equals(fields[i])) {

						data = com.kony.dbputilities.util.CommonUtils.formatDecimal(data);
						isAmountField = true;
					}
					
					if("tranCurr".equals(fields[i]) ) {
						if(data.equalsIgnoreCase("524"))
							data = "NPR";
						else if(data.equalsIgnoreCase("524"))
							data = "USD";
					}
					
					if("tranBillAmou".equals(fields[i]) ) {
						data = String.valueOf(Double.parseDouble(data));
					}
					
					if("tranAmou".equals(fields[i]) ) {
						data = String.valueOf(Double.parseDouble(data));
					}
					
					cell = getCell(new Phrase(data, this.valueFont));
					if (isAmountField) {

						cell.setHorizontalAlignment(Element.ALIGN_RIGHT);
						cell.setVerticalAlignment(Element.ALIGN_BOTTOM);
						Phrase p = new Phrase(data, this.valueFont);
						cell.setPhrase(p);
					}

				}else {
				
					cell = getCell();
				}
				cell.setPaddingBottom(10);
				transTable.addCell(cell);
			}
		} catch (Exception e) {
			alert.prepareError("Error in generation of pdf", e).log();
		}
	}

