	// User Details
	public void getUserDetails(PdfPTable table, String[] userDisplayName, String[] userKeys, JsonObject userDetails) {
		// Font font = new Font(Font.TIMES_ROMAN, 12, Font.ITALIC, Color.BLACK);
		Phrase p2 = null;
		for (int i = 0; i < userDisplayName.length; i++) {

			// Chunk chunk = new Chunk(userDisplayName[i],sourceSansProSemiBold);
			// chunk.setTextRenderMode(PdfContentByte.TEXT_RENDER_MODE_FILL_STROKE, 0.01f,
			// null);
			Phrase p1 = new Phrase(userDisplayName[i], sourceSansProSemiBold);
			PdfPCell cel = new PdfPCell(p1);
			cel.setBorder(0);

			if (null != this.userDetails
					&& (this.userDetails.has(userKeys[i]) && !userDetails.get(userKeys[i]).isJsonNull())) {
				// EBCD-275 : Display the same phone numbers in both PDF and front end
				if (userDisplayName[i].equalsIgnoreCase("Phone: ")) {
					String primaryPhoneNumber = "";
					if (this.userDetails.has("ContactNumbers")) {
						JsonArray phone = this.userDetails.getAsJsonArray("ContactNumbers");
						if(isEncryptEnabled) {
							try {
								phone = AESEncyptor.decryptArray(phone);
							} catch (Exception e) {
								// TODO Auto-generated catch block
								e.printStackTrace();
							}
						}
						for (JsonElement phoneElement : phone) {
							JsonObject phoneObject = phoneElement.getAsJsonObject();
							if (phoneObject.has("isPrimary")
									&& phoneObject.get("isPrimary").getAsString().equals("true")) {
								String countryCode = phoneObject.get("phoneCountryCode").getAsString();
								String phoneNumber = phoneObject.get("phoneNumber").getAsString();
								primaryPhoneNumber = (countryCode.equals("")) ? phoneNumber
										: countryCode + " " + phoneNumber;
								break;
							}
						}
					}

					if (primaryPhoneNumber.equals("")) {
						p2 = new Phrase(userDetails.get(userKeys[i]).getAsString(), valueFont);
						// value.add(new Paragraph(userDetails.get(userKeys[i]).getAsString()));
					} else {
						p2 = new Phrase(primaryPhoneNumber, valueFont);
						// value.add(new Paragraph(primaryPhoneNumber));
					}
				} else {
					p2 = new Phrase(userDetails.get(userKeys[i]).getAsString(), valueFont);
					// value.add(new Paragraph(userDetails.get(userKeys[i]).getAsString()));
				}

				PdfPCell cel2 = new PdfPCell(p2);
				cel2.setBorder(0);
				table.addCell(cel);
				table.addCell(cel2);
			} else {
				alert.prepareError("Error in generation of getUserDetails").log();

			}
		}
	}

