	// Contact Number
	public void getContactNumber(PdfPTable table, JsonObject userDetails) {
		boolean contactAdded = false;
		Phrase p1 = new Phrase(this.contactNumberDisplayName, sourceSansProSemiBold);
		PdfPCell cel = new PdfPCell(p1);
		cel.setBorder(0);
		cel.setPaddingBottom(10);
		table.addCell(cel);
		if (JSONUtil.hasKey(this.userDetails, "ContactNumbers")) {
			JsonArray communications = this.userDetails.getAsJsonArray("ContactNumbers");
			
			if(isEncryptEnabled) {
				try {
					communications = AESEncyptor.decryptArray(communications);
				} catch (Exception e) {
					// TODO Auto-generated catch block
					e.printStackTrace();
				}
			}
			
			for (JsonElement communicationElement : communications) {
				JsonObject communicationObject = communicationElement.getAsJsonObject();
				if (JSONUtil.hasKey(communicationObject, "isPrimary")
						&& communicationObject.get("isPrimary").getAsString().equals("true")) {
					String contactNumber = JSONUtil.hasKey(communicationObject, "Value")
							? communicationObject.get("Value").getAsString()
							: "";
					String PhCountryCode = JSONUtil.hasKey(communicationObject, "phoneCountryCode")
							? communicationObject.get("phoneCountryCode").getAsString()
							: "";
					if(StringUtils.isNotBlank(PhCountryCode))
						contactNumber = PhCountryCode + " " + contactNumber;
					if (StringUtils.isNotBlank(contactNumber)) {

						Phrase p2 = new Phrase(contactNumber, valueFont);
						PdfPCell cel2 = new PdfPCell(p2);
						cel2.setBorder(0);
						cel2.setPaddingBottom(10);

						table.addCell(cel2);
						contactAdded = true;
					}
					break;
				}
			}
		}
		if (!contactAdded) {
			PdfPCell emptyCell1 = new PdfPCell();
			emptyCell1.setBorder(0);
			table.addCell(emptyCell1);
		}

	}

