	@Override
	public byte[] generateCombinedStatementsFile(JsonArray dataObject, String title, String generatedBy,
			String startDate, String endDate, Map<String, String> fieldList, String bankName, String currencyCode,
			String paymentDateFormat, Map<String, Object> otherData) throws Exception {
		PropertyConfigurator.configure(PDFGenerator.class.getClassLoader().getResourceAsStream("log4j.properties"));
		ByteArrayOutputStream os = new ByteArrayOutputStream();
		try {
			this.dateFormat = EnvironmentConfigurationsHandler.getValue("DATE_FORMAT");
			isEncryptEnabled = Boolean
					.valueOf(com.temenos.infinity.api.commons.config.EnvironmentConfigurationsHandler
							.getClientAppProperty("E2E_ENCRYPTION_ENABLED"));
		} catch (Exception e1) {
			// if not able to read the server property use the default value
		}
		try {

			JsonObject accountMappingsObj = (JsonObject) otherData.get("accountMappings");
			otherData.remove("accountMappings");

			Document document = new Document();
			PdfWriter writer = PdfWriter.getInstance(document, os);
			document.setMargins(20, 20, 20, 20);
			diagnostic.prepareDebug("**************Before generating pdf content Combined Statement:").log();
			PdfPTable tableLogoHeader = generateLogoHeader("Combined Statement");

			PageNumeration event = new PageNumeration("Combined");
			writer.setPageEvent(event);

			HeaderFooter footer = generateFooter();
			document.setFooter(footer);
			Paragraph headerParagraph = new Paragraph();
			headerParagraph.add(tableLogoHeader);
			PdfPTable t = new PdfPTable(1);
			PdfPCell c = new PdfPCell();
			c.setBorder(0);
			t.addCell(c);
			t.setSpacingBefore(10);
			t.setSpacingAfter(10);
			headerParagraph.add(t);

			HeaderFooter header = new HeaderFooter(headerParagraph, false);
			header.setBorder(Rectangle.NO_BORDER);

			document.setHeader(header);
			document.open();

			diagnostic.prepareDebug("**************After adding footers").log();

			SimpleDateFormat reportGeneratedDateFormat = new SimpleDateFormat(this.dateFormat + ", hh:mm a");
			String generatedOn = reportGeneratedDateFormat.format(new Date());
			this.currencyCode = StringUtils.isBlank(currencyCode) ? "$" : currencyCode;
			try {
				startDate = StringUtils.isBlank(startDate) ? "NA"
						: HelperMethods.convertDateFormat(startDate, this.dateFormat);
				endDate = StringUtils.isBlank(endDate) ? "NA"
						: HelperMethods.convertDateFormat(endDate, this.dateFormat);
			} catch (ParseException e) {
				alert.prepareError("Error while parsing date" + e).log();
			}

			String phone = "";
			String email = "";
			String address = "";
			String dateRange = "From " + startDate + " to " + endDate;

			PdfPTable outer1 = generateTable(1, 20.0F);
			Chunk linebreak = new Chunk(new LineSeparator((float)0.5, 102, Color.LIGHT_GRAY, Element.ALIGN_LEFT, 2));
			document.add(linebreak);  
			PdfPTable inner1 = generateCombinedStatementHeaderLeft(combinedStatementReportDetails,
					generatedOn, generatedBy, dateRange);
			outer1.addCell(inner1);
			document.add(outer1);

			diagnostic.prepareDebug("**************After adding combined statement page header").log();
			for (String key : accountMappingsObj.keySet()) {
				diagnostic.prepareDebug("**************Iterating accountMappings for user details ").log();
				this.userDetails = (JsonObject) otherData.get(key);

				PdfPTable outer2 = generateTable(5, 10.0F);
				if (JSONUtil.hasKey(this.userDetails, "customers")) {
					JsonArray customerDetails = this.userDetails.getAsJsonArray("customers");
					String coreCustomerId = this.userDetails.get("customerId").toString();
					String coreCustomerName = "";
					for (JsonElement customerDetail : customerDetails) {
						JsonObject customerObj = customerDetail.getAsJsonObject();
						if (customerObj.get("coreCustomerId").toString().equals(coreCustomerId)) {
							coreCustomerName = customerObj.get("coreCustomerName").toString();
						}
					}
					addCustomerDetails(outer2, coreCustomerName, coreCustomerId);
				}
				document.add(outer2);

				PdfPTable outer3 = generateTable(1, 10.0F);
				phone = getContactNumberValue(this.userDetails);
				email = getEmailIdValue(this.userDetails);
				address = getAddressValue(this.userDetails);
				PdfPTable inner3 = generateCombinedStatementHeaderRight(phone, email, address);
				outer3.addCell(inner3);
				document.add(outer3);
				linebreak = new Chunk(new LineSeparator((float)0.5, 102, Color.LIGHT_GRAY, Element.ALIGN_LEFT, 2));
				document.add(linebreak);  
				JsonArray accountsAssociatedToUser = (JsonArray) accountMappingsObj.get(key);
				for (JsonElement eachAccount : accountsAssociatedToUser) {
					diagnostic.prepareDebug("**************Iterating accounts associated to user").log();
					for (int i = 0; i < dataObject.size(); i++) {
						diagnostic.prepareDebug("**************Iterating dataObject to get the account details").log();
						JsonElement accountElement = dataObject.get(i);
						JsonObject accountObject = accountElement.getAsJsonObject();
						String accountName = null;
						String accountNumber = null;
						String accountType = null;
						String currencySymbol = "";
						JsonArray data = new JsonArray();
						if (eachAccount.getAsString().equals(accountObject.get("accountNumber").getAsString())) {
							diagnostic.prepareDebug(
									"**************Comparing with user associated accountNumber to fetch corresponding account details")
									.log();
							if (StringUtils.isNotBlank(accountObject.get("accountName").toString()))
								accountName = accountObject.get("accountName").getAsString();
							if (StringUtils.isNotBlank(accountObject.get("accountNumber").toString()))
								accountNumber = accountObject.get("accountNumber").getAsString();
							if (StringUtils.isNotBlank(accountObject.get("accountType").toString()))
								accountType = accountObject.get("accountType").getAsString();
							if (StringUtils.isNotBlank(accountObject.get("currencySymbol").toString()))
								currencySymbol = accountObject.get("currencySymbol").getAsString();

							if (StringUtils.isNotBlank(accountObject.get("transactionsList").toString()))
								data = accountObject.get("transactionsList").getAsJsonArray();

							PdfPTable accountHeaderTable = generateCombinedStatementAccountHeader(
									accountName, accountNumber, accountType, currencySymbol);
							diagnostic
									.prepareDebug(
											"**************After adding combined statement account  header:" + data)
									.log();
							document.add(accountHeaderTable);

							PdfPTable accountTransactions = getCombinedStatementTable();
							addTransactionsHeader(accountTransactions, combinedStatementHeaders);

							if (null != data && data.size() > 0) {
								for (int j = 0; j < data.size(); j++) {
									try {
										addCombinedStatmentRow(accountTransactions,
												(JsonObject) data.get(j), this.combinedStatementFields);
									} catch (Exception e) {
										alert.prepareError("Error while adding data  to pdf").log();
									}
								}
							}
							accountTransactions.setHeaderRows(1);
							document.add(accountTransactions);

							diagnostic.prepareDebug("**************After adding Transactions").log();
						}
					}
				}
			}

			document.close();
			writer.close();

		} catch (IOException e) {
			// TODO Auto-generated catch block
			alert.prepareError(e.getMessage()).log();

		}
		return os.toByteArray();
	}
	
