	public byte[] generateBlockedFile(JsonArray data, String title, String generatedBy, String startDate,
			String endDate, Map<String, String> fieldList, Map<String, Object> otherData, String filters)
			throws IOException {
		// TODO Auto-generated method stub

		/*
		 * // code snippet for password protection final String USER_PWD="user"; final
		 * String OWNER_PWD="owner"; PdfWriter writer = PdfWriter.getInstance(doc, new
		 * FileOutputStream());
		 * writer.setEncryption(USER_PWD.getBytes(),OWNER_PWD.getBytes(),
		 * PdfWriter.ALLOW_PRINTING, PdfWriter.ENCRYPTION_AES_128);
		 */
		InputStream log4jInputStream = PDFGenerator.class.getClassLoader().getResourceAsStream("log4j.properties");
		PropertyConfigurator.configure(log4jInputStream);
		InputStream is = PDFGenerator.class.getClassLoader().getResourceAsStream(this.imgFileName);
		ByteArrayOutputStream os = new ByteArrayOutputStream();
		try {

			Document document = new Document();
			PdfWriter writer = PdfWriter.getInstance(document, os);
			// setting font family, color
			Font font = new Font(Font.HELVETICA, 12, Font.ITALIC, Color.BLACK);
			Image image = Image.getInstance(IOUtils.toByteArray(is));
			document.open();
			image.setSpacingAfter(70);
			image.scaleAbsoluteHeight(50);
			image.scaleAbsoluteWidth(500);
			document.add(image);
			PdfPTable tableMain = new PdfPTable(2);
			tableMain.getDefaultCell().setBorder(0);
			Phrase p = new Phrase(
					"Note:\nPlease note that the content of this statement will be considered correct if no error is reported within 30 days of reciept of statement. The "
	                + "address of the statement is that on record with the bank as the day of requesting this content.",
					font);
			if (null != otherData.get("userDetails")) {
				this.userDetails = (JsonObject) otherData.get("userDetails");
			}
			PdfPTable tabInner1 = new PdfPTable(2);
			tabInner1.setTotalWidth(new float[] { 72, 216 });
			getUserDetails(tabInner1, userDisplayName, userKeys, userDetails);
			getContactNumber(tabInner1, userDetails);
			getEmailId(tabInner1, userDetails);
			getAddress(tabInner1, userDetails);
			tableMain.setSpacingBefore(10);
			tableMain.setHorizontalAlignment(0);
			tableMain.setWidthPercentage(95);
			tableMain.setComplete(true);
			PdfPTable tabinner = new PdfPTable(1);
			tabinner.addCell(tabInner1);
			tableMain.addCell(tabinner);
			tableMain.addCell(p);
			tableMain.setSpacingAfter(20);
			document.add(tableMain);
			PdfPTable tabAcc = new PdfPTable(1);
			tabAcc.getDefaultCell().setBorder(0);
			addDate(tabAcc, startDate, endDate);
			tabAcc.setHorizontalAlignment(0);
			document.add(tabAcc);

			PdfPTable table = getBlockedTransactionsTable();
			addTransactionsHeader(table, blockedheaders);
			addBlockedTransactionsData(data, table);
			document.add(table);

			document.close();
			writer.close();
		} catch (IOException e) {
			// TODO Auto-generated catch block
			alert.prepareError(e.toString()).log();
		} finally {
			try {
				if (is != null) {
					is.close();
				}
				if (log4jInputStream != null) {
					log4jInputStream.close();
				}
			} catch (Exception e) {
				alert.prepareError(e.toString()).log();
			}
		}
		return os.toByteArray();
	}

	private void addBlockedTransactionsData(JsonArray data, PdfPTable transTable) {
		if (null != data && data.size() > 0) {
			for (int i = data.size() - 1; i >= 0; i--) {
				JsonObject rowData = data.get(i).getAsJsonObject();
				addRow(transTable, rowData, this.blockedfields);
			}
		}
	}
	
	private void addCardTransactionsData(JsonArray data, PdfPTable transTable) throws IOException{
		if (null != data && data.size() > 0) {
			for (int i = data.size() - 1; i >= 0; i--) {
				JsonObject rowData = data.get(i).getAsJsonObject();
				
				addRow(transTable, rowData, this.cardfields);
			}
		}
	}

