	public void addBlockedTransactionsHeader(PdfPTable table, String[] headers) {
		Font font = new Font(Font.HELVETICA, 11, Font.NORMAL, Color.WHITE);

		for (int i = 0; i < headers.length; i++) {
			PdfPCell cell = new PdfPCell();
			cell.setBorder(0);
			cell.setBackgroundColor(new Color(133,26,28));
			cell.setPhrase(new Phrase(headers[i], tableHeaderFont));
			cell.setPaddingBottom(8f);
			cell.setPaddingTop(5f);
			if (i == 0) {
				cell.setPaddingLeft(4f);
			}
			if (i == headers.length - 1) {
				cell.setPaddingRight(4f);
				cell.setHorizontalAlignment(Element.ALIGN_RIGHT);
			}

		/*	if (i == 1) {// Amount field
				cell.setHorizontalAlignment(Element.ALIGN_RIGHT);
			}*/

			table.addCell(cell);
		}
	}
	
	
	// Contact Number
		public String getContactNumberValue(JsonObject userDetails) {
			String contactNumber="";
			if (JSONUtil.hasKey(this.userDetails, "ContactNumbers")) {
				JsonArray communications = this.userDetails.getAsJsonArray("ContactNumbers");
				
				if(isEncryptEnabled) {
					try {
						communications = AESEncyptor.decryptArray(communications);
					} catch (Exception e) {
						// TODO Auto-generated catch block
						e.printStackTrace();
					}
				}
				
				for (JsonElement communicationElement : communications) {
					JsonObject communicationObject = communicationElement.getAsJsonObject();
					if (JSONUtil.hasKey(communicationObject, "isPrimary")
							&& communicationObject.get("isPrimary").getAsString().equals("true")) {
						 contactNumber = JSONUtil.hasKey(communicationObject, "Value")
								? communicationObject.get("Value").getAsString()
								: "";
						break;
					}
				}
			}
			return contactNumber;
		}

