	public String getCoreCustomer(JsonObject userDetails) {
		String coreId="";
		if (JSONUtil.hasKey(this.userDetails, "CoreCustomers")) {
			JsonArray communications = this.userDetails.getAsJsonArray("CoreCustomers");
			diagnostic.prepareDebug("HBL::CoreCustomers: response:" + communications.toString()).log();
			for (JsonElement communicationElement : communications) {
				JsonObject communicationObject = communicationElement.getAsJsonObject();
				if (JSONUtil.hasKey(communicationObject, "coreCustomerID")) {
					coreId = JSONUtil.hasKey(communicationObject, "coreCustomerID")
							? communicationObject.get("coreCustomerID").getAsString()
							: "";
					break;
				}
			}
		}
		return coreId;
	}
	
	private static Map<String, String> getCustomerAccountInfo(String SelectedAccount, String customerid) throws DBPApplicationException {
		diagnostic.prepareDebug("HBL:: getCustomerAccounts call + customerid: " + customerid).log();
		diagnostic.prepareDebug("HBL:: SelectedAccount " + SelectedAccount).log();
		HashMap<String, Object> headers = new HashMap<String, Object>();
		HashMap<String, Object> inputmap = new HashMap<String, Object>();
		inputmap.put("Membership_id", customerid);
		inputmap.put("coreCustomerIdList", customerid);

		Map<String, String> accountInfo = new HashMap<String, String>();
		diagnostic.prepareDebug("HBL::getCustomerAccounts: inputmap:" + inputmap.toString()).log();
		try {
		Result res = DBPServiceExecutorBuilder.builder().withOperationId("getCustomerAccountsCustom")
				.withRequestParameters(inputmap).withServiceId("ArrangementT24ISAccountsCustom")
				.withRequestHeaders(headers).build().getResult();
		diagnostic.prepareDebug("HBL::getCustomerAccounts: response:" + ResultToJSON.convert(res)).log();
		
		JSONObject responseObj = new JSONObject(ResultToJSON.convert(res));
		int count = 0;
		JSONArray accountsArray = responseObj.has("Accounts") ? responseObj.getJSONArray("Accounts") : new JSONArray();
		for (int i = 0; i < accountsArray.length(); i++) {
			JSONObject products = accountsArray.getJSONObject(i);

			JSONArray productArray = products.has("products") ? products.getJSONArray("products") : new JSONArray();

			for (int j = 0; j < productArray.length(); j++) {
				JSONObject account = productArray.getJSONObject(j);
				String acc = account.getString("accountId");
				diagnostic.prepareDebug("HBL:: account ID in loop " + acc).log();
				
				if (StringUtils.isNotBlank(acc) && acc.equalsIgnoreCase(SelectedAccount)) {
					diagnostic.prepareDebug("HBL:: Inside equal loop").log();
					accountInfo.put("accountHolder", account.getString("accountHolder"));
					accountInfo.put("productDescription", account.getString("productDescription"));
					accountInfo.put("currencyCode", account.getString("currencyCode"));
					accountInfo.put("companyCode", account.getString("companyCode"));
					count ++;
					diagnostic.prepareDebug("HBL::Account: res:" + acc).log();
					break;
				}
			}
			if(count != 0)
			break;
		}
		}catch (Exception e) {
			diagnostic.prepareDebug("Excetption in getCustomerAccountInfo:" + e).log();
		}
		return accountInfo;
	}
	
	public static String maskAccountNumber(String data, int fromIndex, int toIndex, String maskWith) {
		if (StringUtils.isNotBlank(data)) {
			StringBuilder maskedPart = new StringBuilder();
			if (StringUtils.isNotBlank(data)) {
				for (int i = fromIndex; i < toIndex; i++)
					maskedPart.append(maskWith);
				return data.replace(data.substring(fromIndex, toIndex), maskedPart.toString());
			}
			return data;
		} else {
			return data;
		}
	}
	
	/** HBL: true when the report title carries a month name, e.g. "June_2026", "Jun-2026". */
	private boolean isMonthlyTitle(String title) {
		if (StringUtils.isBlank(title)) {
			return false;
		}
		String normalizedTitle = StringUtils.lowerCase(StringUtils.trim(title));
		for (int i = 0; i < PDF_MONTH_NAMES.length; i++) {
			String fullMonth = StringUtils.lowerCase(PDF_MONTH_NAMES[i]);
			if (StringUtils.contains(normalizedTitle, fullMonth)
					|| StringUtils.contains(normalizedTitle, StringUtils.substring(fullMonth, 0, 3))) {
				return true;
			}
		}
		return false;
	}

	/** HBL: forces the search start date to the 1st of its month, "2026-6-16" -> "2026-06-01". */
	private String normalizeSearchStartDate(String startDate) {
		int[] dateParts = splitPdfDateParts(startDate);
		if (dateParts == null) {
			return startDate;
		}
		int month = dateParts[1];
		if (month > 12 && dateParts[2] >= 1 && dateParts[2] <= 12) {
			month = dateParts[2];   // value came through as yyyy-dd-MM
		}
		if (month < 1 || month > 12) {
			return startDate;
		}
		return dateParts[0] + "-" + StringUtils.leftPad(String.valueOf(month), 2, '0') + "-01";
	}

